using CustomCodeFramework.Postgres.EntityFramework.Repositories;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Domain.Navigation.Entities;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Persistence.Repositories;public sealed class NavigationMenuRepository(ServiceDbContext db):EfRepository<NavigationMenu,Guid>(db),INavigationMenuRepository{public Task<NavigationMenu?> GetByLocationAsync(string siteKey,string location,CancellationToken ct=default){var s=siteKey.Trim();var l=location.Trim().ToLowerInvariant();return db.NavigationMenus.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.SiteKey==s&&x.Location==l&&!x.IsDeleted,ct);}}
